//! HyperAgent CLI - Subcommand-based interface
//!
//! Usage:
//!   hyper run <prompt>     - Run a coding task (default)
//!   hyper review [ref]     - Review git diff
//!   hyper init             - Build code index
//!   hyper session <cmd>    - Manage sessions
//!   hyper doctor           - System diagnostics
//!   hyper config           - Show config
//!   hyper agents           - List/run agents

use anyhow::Result;
use clap::{Parser, Subcommand, CommandFactory};
use clap_complete::Shell;
use std::path::{Path, PathBuf};

use crate::agent::orchestrator::Orchestrator;
use crate::hooks::HookRegistry;
use crate::index::HyperIndex;
use crate::llm::LlmProvider;
use crate::memory::{MemoryManager, SqliteMemoryStore};
use crate::session::{Session, SessionManager};
use crate::updater::Updater;

pub mod handlers;

/// HyperAgent - Ultra-Fast CLI Coding Agent
///
/// An intelligent coding agent with global code understanding
/// and multi-agent parallel execution.
#[derive(Parser, Debug)]
#[command(name = "hyper", version, about)]
#[command(propagate_version = true)]
pub struct Cli {
    /// The subcommand (omit to enter interactive REPL)
    #[command(subcommand)]
    pub command: Option<Commands>,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Run a coding task with the agent
    Run {
        /// The prompt or task description
        prompt: String,

        /// Path to an image file (for vision-capable models)
        #[arg(short, long)]
        image: Option<PathBuf>,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Number of parallel code agents
        #[arg(long, default_value = "3")]
        agents: usize,

        /// Max tokens for code context per file
        #[arg(long, default_value_t = 4000)]
        context_tokens: u32,

        /// Model to use (overrides config)
        #[arg(long)]
        model: Option<String>,

        /// LLM provider base URL
        #[arg(long, env = "HYPER_LLM_BASE_URL")]
        base_url: Option<String>,

        /// LLM API key
        #[arg(long, env = "HYPER_LLM_API_KEY")]
        api_key: Option<String>,

        /// Skip confirmation before applying changes
        #[arg(long)]
        yes: bool,

        /// Rebuild index from scratch
        #[arg(long)]
        reindex: bool,

        /// Continue from a previous session
        #[arg(long)]
        session: Option<String>,

        /// Agent mode (code/architect/ask/debug)
        #[arg(long, default_value = "code")]
        mode: String,
    },

    /// Review code changes from git diff
    Review {
        /// Git ref to review against (default: unstaged changes)
        #[arg(default_value = "HEAD")]
        against: String,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Model to use
        #[arg(long)]
        model: Option<String>,
    },

    /// Initialize: setup, checks, and build code index
    Init {
        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Force rebuild (alias: --reindex)
        #[arg(long, alias = "reindex")]
        force: bool,

        /// Skip interactive checks (for CI)
        #[arg(long)]
        yes: bool,

        /// Generate project from template (rust-cli, python-fastapi, react-vite-ts, etc.)
        #[arg(long, short)]
        template: Option<String>,

        /// List available project templates
        #[arg(long)]
        list_templates: bool,
    },

    /// Show index statistics
    Stats {
        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Manage sessions
    #[clap(subcommand)]
    Session(SessionAction),

    /// List and switch agent modes
    #[clap(subcommand)]
    Mode(ModeAction),

    /// Manage agent memories (learned knowledge)
    #[clap(subcommand)]
    Memory(MemoryAction),

    /// Manage agent graph (parent/child spawning)
    #[clap(subcommand)]
    Graph(GraphAction),

    /// Manage MCP server connections
    #[clap(subcommand)]
    Mcp(McpAction),

    /// Kanban board for parallel task execution
    #[clap(subcommand)]
    Kanban(KanbanAction),

    /// Manage lifecycle hooks
    #[clap(subcommand)]
    Hooks(HooksAction),

    /// Run system diagnostics
    Doctor,

    /// Run a memory+retrieval benchmark
    #[clap(subcommand)]
    Bench(BenchAction),

    /// Show current configuration
    Config {
        /// Show all config including defaults
        #[arg(long)]
        verbose: bool,
    },

    /// Set a config value (e.g. hyper config set llm.model gpt-4)
    ConfigSet {
        /// Config key path (e.g. "llm.model", "agent.confirm")
        key: String,
        /// Config value
        value: String,
    },

    /// Get a config value
    ConfigGet {
        /// Config key path
        key: String,
    },

    /// List all available config keys
    ConfigList,

    /// Generate shell completions
    Completions {
        /// Shell to generate completions for (bash, zsh, fish, powershell, elvish)
        shell: String,
    },

    /// Interactive setup wizard (first-time configuration)
    Setup {
        /// Run the interactive tutorial (first-time user onboarding)
        #[arg(long)]
        tutorial: bool,
    },

    /// List and run available agents
    Agents {
        /// Agent name to run (lists all if not provided)
        name: Option<String>,

        /// Agent prompt/task
        message: Vec<String>,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Initialize default configuration file
    ConfigInit,

    /// Commit staged changes with auto-generated message
    Commit {
        /// Custom commit message (auto-generated if not provided)
        #[arg(short, long)]
        message: Option<String>,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Launch terminal dashboard (TUI)
    #[cfg(feature = "tui")]
    Tui,

    /// Search the web
    Search {
        /// Search query
        query: Vec<String>,

        /// Max results to show
        #[arg(long, default_value = "5")]
        max: usize,
    },

    /// Scaffold a new project from template
    Scaffold {
        /// Project name
        name: String,

        /// Project type (rust, python, ts)
        #[arg(short, long, default_value = "rust")]
        type_: String,

        /// Output directory
        #[arg(short, long, default_value = ".")]
        dir: PathBuf,
    },

    /// Build and deploy Docker image
    Deploy {
        /// Docker image tag
        #[arg(short, long, default_value = "hyperagent-app")]
        tag: String,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Show colorized diff for staged or unstaged changes
    Diff {
        /// Git ref to diff against (default: unstaged changes)
        #[arg(default_value = "HEAD")]
        against: String,

        /// Show staged changes instead
        #[arg(short, long)]
        staged: bool,

        /// Show side-by-side diff view
        #[arg(long)]
        side_by_side: bool,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Run benchmark evaluations
    Eval {
        /// Specific task name to run (runs all if not specified)
        #[arg(long)]
        task: Option<String>,

        /// List available tasks
        #[arg(long)]
        list: bool,
    },

    /// Build/query knowledge base (RAG)
    Knowledge {
        /// Action: build | search
        action: String,

        /// Search query (required for search action)
        query: Option<Vec<String>>,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Analyze project dependencies
    Deps {
        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Generate unit tests for a file
    TestGen {
        /// File to generate tests for
        file: PathBuf,

        /// Specific function to test
        #[arg(short, long)]
        function: Option<String>,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Run unit, integration, or E2E tests
    Test {
        /// Test mode: unit, integration, e2e, gen
        #[arg(short, long, default_value = "all")]
        mode: String,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,
    },

    /// Find references to a symbol across the codebase
    FindRefs {
        /// Symbol name to search for
        symbol: String,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Show context lines around matches
        #[arg(long, default_value_t = 0)]
        context: usize,
    },

    /// Rename a symbol across all files (cross-file refactoring)
    Rename {
        /// Current symbol name
        old: String,

        /// New symbol name
        new: String,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Dry-run: show what would change without applying
        #[arg(long)]
        dry_run: bool,
    },

    /// Show the last agent run log (timing, changes, errors)
    Log {
        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Show full log instead of summary
        #[arg(long)]
        verbose: bool,
    },

    /// Undo the last agent run — revert all changes via git checkout
    Undo {
        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Skip confirmation
        #[arg(long)]
        yes: bool,
    },

    /// Auto-generate CHANGELOG.md from conventional commits
    Changelog {
        /// Output file path (default: CHANGELOG.md)
        #[arg(short, long)]
        output: Option<PathBuf>,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Number of recent commits to include (default: all)
        #[arg(long)]
        commits: Option<usize>,
    },

    /// Create a GitHub PR from current branch with auto-generated description
    Pr {
        /// Title (auto-generated from branch name + commits if not provided)
        #[arg(short, long)]
        title: Option<String>,

        /// Base branch (default: main)
        #[arg(short, long, default_value = "main")]
        base: String,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Push before creating PR
        #[arg(long)]
        push: bool,

        /// Open PR URL in browser
        #[arg(long)]
        open: bool,

        /// Dry-run: show what would be created without submitting
        #[arg(long)]
        dry_run: bool,
    },

    /// Watch mode — auto-run agent when files change
    Watch {
        /// Prompt to run on each change
        prompt: Vec<String>,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Debounce interval in seconds (default: 2)
        #[arg(long, default_value_t = 2)]
        debounce: u64,

        /// File patterns to watch (e.g., '*.rs')
        #[arg(long)]
        pattern: Option<String>,

        /// Skip confirmation
        #[arg(long)]
        yes: bool,
    },

    /// Explain code with LLM — analyze a file or function
    Explain {
        /// File path or function name to explain
        target: String,

        /// Project root directory
        #[arg(long, short, default_value = ".")]
        dir: PathBuf,

        /// Model to use
        #[arg(long)]
        model: Option<String>,
    },

    /// Check for and install HyperAgent updates from GitHub Releases
    SelfUpdate {
        /// Only check for updates (don't install)
        #[arg(long)]
        check: bool,
    },

    /// View usage analytics and statistics
    Analytics {
        /// Serve analytics web dashboard
        #[arg(long, short)]
        web: bool,

        /// Port for web dashboard (default: 8099)
        #[arg(long, default_value_t = 8099)]
        port: u16,

        /// Output as JSON for external BI tools
        #[arg(long)]
        json: bool,
    },

    /// Manage billing, subscription, and license
    #[clap(subcommand)]
    Billing(BillingAction),

    /// Sync memories, skills, and config to/from cloud
    #[clap(subcommand)]
    Sync(SyncAction),

    /// Manage team workspace
    #[clap(subcommand)]
    Team(TeamAction),

    /// Start SaaS web server (browser-based agent)
    Saas {
        /// Port to listen on
        #[arg(long, short, default_value_t = 3000)]
        port: u16,
    },
}

